            HttpClient client = HttpClient.newBuilder().cookieHandler(cookies).build();
            URI root = URI.create("http://127.0.0.1:" + server.port());
            String token = [REDACTED_CREDENTIAL]
            assertEquals(200, post(client, root.resolve("/api/v1/auth/local/exchange"), "{\"token\":\"" + token + "\"}").statusCode());
            assertEquals(401, post(client, root.resolve("/api/v1/auth/local/exchange"), "{\"token\":\"" + token + "\"}").statusCode());
            JsonNode created = json(post(client, root.resolve("/api/v1/sessions"), "{\"workingDirectory\":\".\"}"));
            String sessionId = created.path("sessionId").asText();
            assertEquals(202, post(client, root.resolve("/api/v1/sessions/" + sessionId + "/prompt"),
