    @Test
    void localHostTransportsRealHcpHandshakeAckAndReplayFrames() throws Exception {
        var provider = new ScriptedModelProvider().enqueue(List.of(
                new ScriptedModelProvider.Step.Text("hello"),
                new ScriptedModelProvider.Step.Complete(io.github.diodeme.ji.ai.Usage.ZERO,
                        io.github.diodeme.ji.ai.ModelStreamEvent.StopReason.STOP)));
        PermissionBroker permissions = new PermissionBroker(Clock.systemUTC());
        var hostStore = new MemoryHostStore();
        try (var runtime = new AgentRuntimeBuilder().provider(provider).sessionStore(hostStore)
                .permissionDecider(permissions).build();
             var sessions = new SessionApplicationService(runtime);
             var server = new LocalHostServer(sessions, permissions,
                     new PromptApplicationService(sessions, hostStore),
                     new ModelRef("faux", "faux-1"), new LocalTokenService(new SecureRandom(), Clock.systemUTC()))) {
            var cookies = new CookieManager(null, CookiePolicy.ACCEPT_ALL);
            HttpClient client = HttpClient.newBuilder().cookieHandler(cookies).build();
            URI root = URI.create("http://127.0.0.1:" + server.port());
            assertEquals(200, post(client, root.resolve("/api/v1/auth/local/exchange"),
                    "{\"token\":\"" + server.issueLaunchToken() + "\"}").statusCode());
            String sessionId = json(post(client, root.resolve("/api/v1/sessions"),
                    "{\"workingDirectory\":\".\"}")).path("sessionId").asText();
            Envelope welcome = hcp(client, root, Envelope.newBuilder().setConnectionId("connection-1")
                    .setClientHello(ClientHello.newBuilder().setMinProtocolVersion(1).setMaxProtocolVersion(1)
                            .setClientId("client-1").addRequiredCapabilities("command.ack")).build()).getFirst();
            assertTrue(welcome.hasServerWelcome());
            Envelope ack = hcp(client, root, Envelope.newBuilder().setConnectionId("connection-1")
                    .setCommand(Command.newBuilder().setCommandId("command-hcp").setSessionId(sessionId)
                            .setExpectedRevision(0).setPayload(ByteString.copyFromUtf8("hello"))).build()).getFirst();
            assertTrue(ack.hasCommandAck());
            awaitTranscript(client, root, sessionId, 2);
            List<Envelope> replay = hcp(client, root, Envelope.newBuilder().setConnectionId("connection-1")
                    .setReplayRequest(ReplayRequest.newBuilder().setSessionId(sessionId)
                            .setLastAckSeq(0).setSnapshotRevision(0)).build());
            assertTrue(replay.getFirst().hasSnapshotChunk());
            assertTrue(replay.getFirst().getSnapshotChunk().getPayload().toStringUtf8().contains("hello"));
        }
    }

    @Test
    void refreshRestoresToolResultAndTransientProgressDoesNotConsumeDurableSequence() throws Exception {
        var provider = new ScriptedModelProvider()
                .enqueue(List.of(new ScriptedModelProvider.Step.Text("Working"),
                        new ScriptedModelProvider.Step.Tool("call-1", "echo", java.util.Map.of("value", "hello")),
                        new ScriptedModelProvider.Step.Complete(io.github.diodeme.ji.ai.Usage.ZERO,
                                io.github.diodeme.ji.ai.ModelStreamEvent.StopReason.TOOL_USE)))
                .enqueue(List.of(new ScriptedModelProvider.Step.Text("Done"),
                        new ScriptedModelProvider.Step.Complete(new io.github.diodeme.ji.ai.Usage(2, 1, 0, 0, 0),
                                io.github.diodeme.ji.ai.ModelStreamEvent.StopReason.STOP)));
        PermissionBroker permissions = new PermissionBroker(Clock.systemUTC());
        var hostStore = new MemoryHostStore();
        try (var runtime = new AgentRuntimeBuilder().provider(provider).sessionStore(hostStore)
                .permissionDecider((request, cancellation) -> java.util.concurrent.CompletableFuture.completedFuture(
                        PermissionDecider.Decision.allow(request, java.time.Instant.now())))
                .tool(ToolDefinition.sync("echo", "Echo input", java.util.Map.of("type", "object"),
                        (arguments, cancellation) -> ToolDefinition.ToolResult.text("echoed hello")))
                .build();
             var sessions = new SessionApplicationService(runtime);
             var server = new LocalHostServer(sessions, permissions,
                     new PromptApplicationService(sessions, hostStore),
                     new ModelRef("faux", "faux-1"), new LocalTokenService(new SecureRandom(), Clock.systemUTC()))) {
            var cookies = new CookieManager(null, CookiePolicy.ACCEPT_ALL);
            HttpClient client = HttpClient.newBuilder().cookieHandler(cookies).build();
            URI root = URI.create("http://127.0.0.1:" + server.port());
            assertEquals(200, post(client, root.resolve("/api/v1/auth/local/exchange"),
                    "{\"token\":\"" + server.issueLaunchToken() + "\"}").statusCode());
            String sessionId = json(post(client, root.resolve("/api/v1/sessions"),
                    "{\"workingDirectory\":\".\"}")).path("sessionId").asText();
            assertEquals(202, post(client, root.resolve("/api/v1/sessions/" + sessionId + "/prompt"),
                    "{\"commandId\":\"command-tool\",\"text\":\"echo hello\"}").statusCode());
            JsonNode snapshot = awaitTranscript(client, root, sessionId, 4);
            assertEquals("echoed hello", snapshot.path("transcript").get(2).path("text").asText());
            assertEquals("call-1", snapshot.path("transcript").get(2).path("toolCallId").asText());
            assertEquals(1, snapshot.path("lastEventSeq").asLong());
            assertTrue(snapshot.path("lastStreamSeq").asLong() > 0);
            assertEquals("completed", snapshot.path("outcome").asText());
            assertEquals(3, snapshot.path("usage").path("inputTokens").asLong()
                    + snapshot.path("usage").path("outputTokens").asLong());
            JsonNode events = json(client.send(HttpRequest.newBuilder(root.resolve(
                    "/api/v1/sessions/" + sessionId + "/events?after=0&afterStream=0")).GET().build(),
                    HttpResponse.BodyHandlers.ofString()));
            assertTrue(java.util.stream.StreamSupport.stream(events.path("events").spliterator(), false)
                    .anyMatch(event -> "tool_changed".equals(event.path("type").asText())
                            && "echoed hello".equals(event.path("result").asText())
                            && !event.has("eventSeq") && event.path("streamSeq").asLong() > 0));
            assertEquals(1, java.util.stream.StreamSupport.stream(events.path("events").spliterator(), false)
                    .filter(event -> "session_snapshot".equals(event.path("type").asText()))
                    .mapToLong(event -> event.path("eventSeq").asLong()).findFirst().orElseThrow());
        }
    }

    @Test
    void realAcpAndWebAdaptersDriveOneSessionAndConvergeAfterRefresh() throws Exception {
        var provider = new ScriptedModelProvider()
                .enqueue(List.of(new ScriptedModelProvider.Step.Text("ACP working"),
                        new ScriptedModelProvider.Step.Tool("call-acp", "echo", Map.of("value", "acp")),
                        new ScriptedModelProvider.Step.Complete(new io.github.diodeme.ji.ai.Usage(2, 1, 0, 0, 0),
                                io.github.diodeme.ji.ai.ModelStreamEvent.StopReason.TOOL_USE)))
                .enqueue(List.of(new ScriptedModelProvider.Step.Text("ACP done"),
                        new ScriptedModelProvider.Step.Complete(new io.github.diodeme.ji.ai.Usage(3, 2, 0, 0, 0),
                                io.github.diodeme.ji.ai.ModelStreamEvent.StopReason.STOP)))
                .enqueue(List.of(new ScriptedModelProvider.Step.Text("Web reply"),
                        new ScriptedModelProvider.Step.Complete(new io.github.diodeme.ji.ai.Usage(4, 2, 0, 0, 0),
                                io.github.diodeme.ji.ai.ModelStreamEvent.StopReason.STOP)));
        PermissionBroker permissions = new PermissionBroker(Clock.systemUTC());
        var hostStore = new MemoryHostStore();
        try (var runtime = new AgentRuntimeBuilder().provider(provider).sessionStore(hostStore)
                .permissionDecider(permissions)
                .tool(ToolDefinition.sync("echo", "Echo input", Map.of("type", "object"),
                        (arguments, cancellation) -> ToolDefinition.ToolResult.text("echoed " + arguments.get("value"))))
                .build();
             var sessions = new SessionApplicationService(runtime)) {
            var prompts = new PromptApplicationService(sessions, hostStore);
            String sessionId;
            try (var acp = new AcpHarness(sessions, permissions, prompts)) {
                acp.request(1, "initialize", Map.of("protocolVersion", 1, "clientCapabilities", Map.of()));
                sessionId = acp.request(2, "session/new", Map.of("cwd", ".", "mcpServers", List.of()))
                        .path("result").path("sessionId").asText();
                JsonNode terminal = acp.prompt(3, sessionId, "ACP prompt", "acp-command");
                assertEquals("end_turn", terminal.path("result").path("stopReason").asText());
                assertTrue(acp.toolStatuses.contains("completed"));
            }

            try (var server = new LocalHostServer(sessions, permissions, prompts,
                    new ModelRef("faux", "faux-1"), new LocalTokenService(new SecureRandom(), Clock.systemUTC()))) {
                var cookies = new CookieManager(null, CookiePolicy.ACCEPT_ALL);
                HttpClient client = HttpClient.newBuilder().cookieHandler(cookies).build();
                URI root = URI.create("http://127.0.0.1:" + server.port());
                assertEquals(200, post(client, root.resolve("/api/v1/auth/local/exchange"),
                        "{\"token\":\"" + server.issueLaunchToken() + "\"}").statusCode());
                assertEquals(202, post(client, root.resolve("/api/v1/sessions/" + sessionId + "/prompt"),
                        "{\"commandId\":\"web-command\",\"text\":\"Web prompt\"}").statusCode());
                JsonNode webSnapshot = awaitTranscript(client, root, sessionId, 6);
                List<String> canonical = sessions.transcript(sessionId).stream().map(message -> message.text()).toList();
                List<String> webProjection = new ArrayList<>();
                webSnapshot.path("transcript").forEach(message -> webProjection.add(message.path("text").asText()));
                assertEquals(List.of("ACP prompt", "ACP working", "echoed acp", "ACP done", "Web prompt", "Web reply"), canonical);
                assertEquals(canonical, webProjection);
                assertEquals("call-acp", webSnapshot.path("transcript").get(2).path("toolCallId").asText());
                assertEquals(14, webSnapshot.path("usage").path("inputTokens").asLong()
                        + webSnapshot.path("usage").path("outputTokens").asLong());
                assertEquals("completed", webSnapshot.path("outcome").asText());
                JsonNode refreshed = json(client.send(HttpRequest.newBuilder(root.resolve(
                        "/api/v1/sessions/" + sessionId + "/snapshot")).GET().build(), HttpResponse.BodyHandlers.ofString()));
                assertEquals(webSnapshot.path("transcript"), refreshed.path("transcript"));
                assertEquals(webSnapshot.path("usage"), refreshed.path("usage"));
                assertEquals(webSnapshot.path("outcome"), refreshed.path("outcome"));
            }
        }
    }

    private static final class AcpHarness implements AutoCloseable {
        private static final ObjectMapper MAPPER = new ObjectMapper();
        private final PipedInputStream serverInput = new PipedInputStream();
        private final PipedOutputStream serverOutput = new PipedOutputStream();
        private final PipedInputStream clientInput;
        private final PipedOutputStream clientOutput;
        private final BufferedReader reader;
        private final PrintWriter writer;
        private final AcpV1Server server;
        private final Thread thread;
        private final List<String> toolStatuses = new ArrayList<>();

        AcpHarness(SessionApplicationService sessions, PermissionBroker permissions,
                   PromptApplicationService prompts) throws Exception {
            clientInput = new PipedInputStream(serverOutput);
            clientOutput = new PipedOutputStream(serverInput);
            reader = new BufferedReader(new InputStreamReader(clientInput, StandardCharsets.UTF_8));
            writer = new PrintWriter(clientOutput, true, StandardCharsets.UTF_8);
            server = new AcpV1Server(serverInput, serverOutput, sessions, permissions, prompts,
                    new ModelRef("faux", "faux-1"));
            thread = Thread.startVirtualThread(server::run);
        }

        JsonNode request(long id, String method, Object params) throws Exception {
            writer.println(MAPPER.writeValueAsString(Map.of(
                    "jsonrpc", "2.0", "id", id, "method", method, "params", params)));
            return readResponse(id);
        }

        JsonNode prompt(long id, String sessionId, String text, String commandId) throws Exception {
            return request(id, "session/prompt", Map.of("sessionId", sessionId,
                    "prompt", List.of(Map.of("type", "text", "text", text)),
                    "_meta", Map.of("commandId", commandId)));
        }

        private JsonNode readResponse(long expectedId) throws Exception {
            while (true) {
                String line = reader.readLine();
                if (line == null) throw new AssertionError("ACP stream closed before response " + expectedId);
                JsonNode message = MAPPER.readTree(line);
                if (message.has("id") && message.path("id").asLong() == expectedId) return message;
                if ("session/update".equals(message.path("method").asText())) {
                    JsonNode update = message.path("params").path("update");
                    String type = update.path("sessionUpdate").asText();
                    if ("tool_call".equals(type) || "tool_call_update".equals(type)) {
                        toolStatuses.add(update.path("status").asText());
                    }
                } else if ("session/request_permission".equals(message.path("method").asText())) {
                    var response = MAPPER.createObjectNode();
                    response.put("jsonrpc", "2.0");
                    response.set("id", message.path("id"));
                    response.set("result", MAPPER.valueToTree(
                            Map.of("outcome", Map.of("outcome", "selected", "optionId", "allow"))));
                    writer.println(MAPPER.writeValueAsString(response));
                }
            }
        }

        @Override
        public void close() {
            try {
                clientOutput.close();
                thread.join(TimeUnit.SECONDS.toMillis(5));
                if (thread.isAlive()) throw new AssertionError("ACP server did not stop");
                server.close();
                reader.close();
                clientInput.close();
                serverOutput.close();
                serverInput.close();
            } catch (java.io.IOException exception) {
                throw new java.io.UncheckedIOException(exception);
            } catch (InterruptedException exception) {
                Thread.currentThread().interrupt();
                throw new IllegalStateException("interrupted while closing ACP harness", exception);
            }
        }
    }

    private static JsonNode awaitTranscript(HttpClient client, URI root, String sessionId, int size) throws Exception {
        Instant deadline = Instant.now().plus(Duration.ofSeconds(5));
        JsonNode snapshot;
        do {
            snapshot = json(client.send(HttpRequest.newBuilder(root.resolve(
                    "/api/v1/sessions/" + sessionId + "/snapshot")).GET().build(),
                    HttpResponse.BodyHandlers.ofString()));
            if (snapshot.path("transcript").size() >= size
                    && !snapshot.path("outcome").asText().isBlank()) return snapshot;
            if (Instant.now().isAfter(deadline)) throw new AssertionError(
                    "snapshot did not reach transcript size " + size + ": " + snapshot);
            Thread.sleep(10);
        } while (true);
    }

    private static List<Envelope> hcp(HttpClient client, URI root, Envelope envelope) throws Exception {
        HttpResponse<byte[]> response = client.send(HttpRequest.newBuilder(root.resolve("/api/v1/hcp"))
                .header("Content-Type", "application/x-protobuf")
                .POST(HttpRequest.BodyPublishers.ofByteArray(envelope.toByteArray())).build(),
                HttpResponse.BodyHandlers.ofByteArray());
        assertEquals(200, response.statusCode());
        var result = new java.util.ArrayList<Envelope>();
        try (var input = new java.io.ByteArrayInputStream(response.body())) {
            Envelope item;
            while ((item = Envelope.parseDelimitedFrom(input)) != null) result.add(item);
        }
        return List.copyOf(result);
    }

    private static HttpResponse<String> post(HttpClient client, URI uri, String body) throws Exception {
        return client.send(HttpRequest.newBuilder(uri).header("Content-Type", "application/json")
                .POST(HttpRequest.BodyPublishers.ofString(body)).build(), HttpResponse.BodyHandlers.ofString());
    }

    private static JsonNode json(HttpResponse<String> response) throws Exception {
        return new ObjectMapper().readTree(response.body());
    }
}

